#[test]
fn refused_deactivation_preserves_prepared_buffers_and_prevents_reconfiguration() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    let mut plugin = plugin_fixture(&trace, &state);
    plugin.setup_processing().unwrap();
    plugin.activate().unwrap();
    let prepared = &**plugin.runtime.process_data.as_ref().unwrap() as *const HostProcessData;
    let setup = plugin.control.applied_setup;
    state.fail_deactivate.store(true, Ordering::Relaxed);
    trace.clear();
    assert!(plugin.reconfigure(44100.0, 32).is_err());
    assert!(plugin
        .set_process_mode(crate::plugin::ProcessMode::Offline)
        .is_err());
    assert!(plugin.control.is_active);
    assert_eq!(plugin.control.applied_setup, setup);
    assert_eq!(
        &**plugin.runtime.process_data.as_ref().unwrap() as *const HostProcessData,
        prepared
    );
    assert_eq!(
        trace.methods(),
        [
            ("component", "setActive(false)"),
            ("component", "setActive(false)")
        ]
    );
    // Cleanup remains in the original confirmed lifecycle after the mock lifts its refusal.
    state.fail_deactivate.store(false, Ordering::Relaxed);
}

#[test]
fn facade_state_failure_updates_processing_flag_and_retries_real_setup() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    let internal = plugin_fixture(&trace, &state);
    let plugin = crate::plugin::Plugin {
        info: internal.info.clone(),
        compatibility: Vec::new(),
        is_processing: false,
        sample_rate: 48000.0,
        block_size: 16,
        audio_levels: Arc::new(Mutex::new(crate::audio::AudioLevels::new(1))),
        parameter_change_callback: None,
        audio_callback: None,
        internal: Some(Box::new(internal)),
    };
    let mut owner = crate::plugin::MainThreadPlugin::from_in_process(plugin);
    owner.start_processing().unwrap();
    state.expand_on_state.store(true, Ordering::Relaxed);
    state.fail_setup.store(true, Ordering::Relaxed);
    let snapshot = encode_state_snapshot(&StateSnapshot {
        component: vec![1],
        controller: None,
    })
    .unwrap();
    assert!(owner
        .load_state_with_context(&snapshot, &StateContext::Project)
        .is_err());
    assert!(!owner.is_processing());
    // This must enter setup again and fail, rather than return Ok from an obsolete true flag.
    assert!(owner.start_processing().is_err());
    state.fail_setup.store(false, Ordering::Relaxed);
    owner.start_processing().unwrap();
    assert!(owner.is_processing());
    assert_eq!(owner.output_channel_count(), 4);
    let mut buffers = AudioBuffers::new(0, 4, 16, 48000.0);
    owner.process_audio(&mut buffers).unwrap();
    assert_eq!(*state.processed_layouts.lock().unwrap(), [vec![2, 2]]);
}

#[test]
fn transferred_initialization_guard_releases_before_later_load_failure_unloads_module() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    // Match loader declaration order: guard predates the completed plugin owner.
    let mut initialized;
    let mut plugin = plugin_fixture(&trace, &state);
    initialized = InitializedComponent::new(plugin.control.component.clone());
    initialized.attach_controller(plugin.control.controller.clone(), true);
    trace.clear();
    initialized.finish_transfer();
    assert_eq!(
        trace.methods(),
        [("component", "release"), ("component", "release")]
    );
    // A subsequent fallible post-transfer operation fails, triggering ordinary owner Drop.
    state.fail_setup.store(true, Ordering::Relaxed);
    assert!(plugin.setup_processing().is_err());
    drop(plugin);
    let calls = trace.methods();
    let module = calls
        .iter()
        .position(|call| *call == ("module", "drop"))
        .unwrap();
    assert!(!calls[module + 1..]
        .iter()
        .any(|(_, method)| *method == "release"));
    assert!(calls[..module].contains(&("component", "drop")));
    assert!(calls[..module].contains(&("factory", "drop")));
    assert_eq!(trace.lifecycle(), [("component", "terminate")]);
}

#[test]
fn io_restart_rebuilds_layout_and_failed_rebuild_stays_quiescent() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    let mut plugin = plugin_fixture(&trace, &state);
    let handler = ComWrapper::new(ComponentHandler::new(Arc::new(Mutex::new(Vec::new()))));
    let callback = handler.to_com_ptr::<IComponentHandler>().unwrap();
    plugin.control.component_handler = Some(handler);
    plugin.start_processing().unwrap();
    state.output_buses.store(2, Ordering::Relaxed);
    state.channels.store(2, Ordering::Relaxed);
    assert_eq!(
        unsafe { callback.restartComponent(RestartFlags_::kIoChanged) },
        kResultOk
    );
    assert!(plugin.service_host_requests().unwrap().io_changed());
    assert_prepared_layout(&plugin, 2, 2);
    process_and_assert_samples(&mut plugin, 2, 2);
    state.fail_setup.store(true, Ordering::Relaxed);
    assert_eq!(
        unsafe { callback.restartComponent(RestartFlags_::kIoChanged) },
        kResultOk
    );
    assert!(plugin.service_host_requests().is_err());
    assert!(!plugin.runtime.is_processing);
    assert!(!plugin.control.is_active);
    assert!(plugin.runtime.process_data.is_none());
    trace.clear();
    let mut buffers = AudioBuffers::new(0, 4, 16, 48000.0);
    assert!(plugin.process(&mut buffers).is_err());
    assert!(!trace
        .methods()
        .iter()
        .any(|(_, method)| *method == "process"));
    state.fail_setup.store(false, Ordering::Relaxed);
    plugin.start_processing().unwrap();
    assert_prepared_layout(&plugin, 2, 2);
}
